txt = '"sheerTable": ' + json.dumps(rec, ensure_ascii=False) + ', '
a = '"cheeks": {'
assert s.count(a) == 1
s = s.replace(a, txt + a)
json.loads(s)
open(p, 'w').write(s); print('vessels ok')
